script:
html { scroll-behavior: smooth; }
::selection { background: #0B0B0B; color: #FFFFFF; }

/* reveals sharpen into focus, like an eye exam settling on the right lens */
html.op-js .op-focus { opacity: 0.25; filter: blur(9px); }
html.op-js .op-focus.op-in {
  opacity: 1; filter: none;
  transition: opacity 0.9s cubic-bezier(0.22, 1, 0.36, 1),
    filter 0.9s cubic-bezier(0.22, 1, 0.36, 1);
}
html.op-js .op-d2.op-in { transition-delay: 0.07s; }
html.op-js .op-d3.op-in { transition-delay: 0.14s; }
html.op-js .op-d4.op-in { transition-delay: 0.21s; }
html.op-js .op-d5.op-in { transition-delay: 0.28s; }
html.op-js .op-d6.op-in { transition-delay: 0.35s; }

.op-ul {
  background-image: linear-gradient(currentColor, currentColor);
  background-position: left bottom; background-repeat: no-repeat;
  background-size: 0% 1.5px;
  transition: background-size 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}
.op-ul:hover { background-size: 100% 1.5px; }
.op-btn { transition: opacity 0.2s ease; }
.op-btn:hover { opacity: 0.82; }
.op-card { transition: box-shadow 0.35s ease, transform 0.35s ease; }
.op-card:hover { box-shadow: 6px 6px 0 #F4F4F4; transform: translate(-2px, -2px); }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}
